def _check_display(disp):
    """Validate the display-name region that precedes '<'."""
    d = disp.strip(' \t')
    if not d:
        return
    if d[0] == '"':
        i = 1
        n = len(d)
        esc = False
        closed = False
        while i < n:
            c = d[i]
            if esc:
                esc = False
            elif c == '\\':
                esc = True
            elif c == '"':
                closed = True
                i += 1
                break
            i += 1
        if not closed:
            _syntax()
        if d[i:].strip(' \t'):
            _syntax()
    else:
        for tok in d.split():
            for c in tok:
                if c not in TOKEN_CHARS:
                    _syntax()


def _scan_address(s, i):
    """Parse one address in s starting at index i.

    Returns (normalized_uri, index_after_address).  Raises Reject('syntax').
    """
    n = len(s)
    j = i
    inq = False
    esc = False
    lt = -1
    while j < n:
        c = s[j]
        if inq:
            if esc:
                esc = False
            elif c == '\\':
                esc = True
            elif c == '"':
                inq = False
        elif c == '"':
            inq = True
        elif c == '<':
            lt = j
            break
        j += 1
    if lt < 0:
        if inq or esc:
            _syntax()
        # A bare URI ends at the first SP/HTAB or ';' (the caller decides
        # whether anything may legitimately follow).
        k = i
        while k < n and s[k] != ' ' and s[k] != '\t' and s[k] != ';':
            k += 1
        uri = parse_uri(s[i:k])
        if uri is None:
            _syntax()
        return uri, k
    if i < lt:
        _check_display(s[i:lt])
    e = s.find('>', lt + 1)
    if e < 0:
        _syntax()
    uri = parse_uri(s[lt + 1:e].strip(' \t'))
    if uri is None:
        _syntax()
    return uri, e + 1


def _parse_tagged(value):
    """Parse a From/To value: one address plus an optional ;tag parameter."""
    n = len(value)
    uri, j = _scan_address(value, 0)
    tag = None
    while j < n and value[j] in ' \t':
        j += 1
    if j >= n:
        return uri, tag
    if value[j] != ';':
        _syntax()
    j += 1
    while j < n and value[j] in ' \t':
        j += 1
    k = j
    while k < n and value[k] not in ' \t=':
        k += 1
    name = value[j:k]
    while k < n and value[k] in ' \t':
        k += 1
    if k >= n or value[k] != '=':
        _syntax()
    k += 1
    while k < n and value[k] in ' \t':
        k += 1
    m = k
    while m < n and value[m] not in ' \t':
        m += 1
    tag_value = value[k:m]
    if not tag_value or len(tag_value) > 128:
        _syntax()
    for c in tag_value:
        if c not in TOKEN_CHARS:
            _syntax()
    while m < n and value[m] in ' \t':
        m += 1
    if m != n:
        _syntax()
    if name.lower() != 'tag':
        _syntax()
    return uri, tag_value


def _parse_plain_address(value):
    """Parse a PPI/RPID value: exactly one address, no header parameters."""
    uri, j = _scan_address(value, 0)
    if value[j:].strip(' \t'):
        _syntax()
    return uri


def _split_pai(value):
    """Split a PAI value on commas outside quoted strings and brackets."""
    parts = []
    n = len(value)
    start = 0
    inq = False
    esc = False
    depth = 0
    for i, c in enumerate(value):
        if inq:
            if esc:
                esc = False
            elif c == '\\':
                esc = True
            elif c == '"':
                inq = False
        elif c == '"':
            inq = True
        elif c == '<':
            depth += 1
        elif c == '>':
            depth -= 1
        elif c == ',' and depth == 0:
            parts.append(value[start:i])
            start = i + 1
    parts.append(value[start:])
    return parts


def _parse_pai_values(raw_values):
    addresses = []
    for raw in raw_values:
        for part in _split_pai(raw):
            part = part.strip(' \t')
            if not part:
                _syntax()
            uri, j = _scan_address(part, 0)
            if part[j:].strip(' \t'):
                _syntax()
            addresses.append(uri)
    if len(addresses) > 2:
        _syntax()
    if len(addresses) == 2:
        sip_count = 0
        for uri in addresses:
            if uri.startswith('sip:'):
                sip_count += 1
        if sip_count != 1:
            _syntax()
    return addresses


